        HUNTER = {
            [1] = { name = "T0.5 · Bracers", lv = 58, zone = "Ironforge / Orgrimmar", rew = { 22011 }, note = "The first stage upgrades only the bracers. Find your faction's contact in your capital and hand in the materials and your old bracers; this step also unlocks every later stage.", flow = {
                { id = 8906, sl = 58, s = "A", q = "An Earnest Proposition", f = "Deliana", fl = "Ironforge 42.4,53.2", fn = 16013, t = "Deliana", tl = "Ironforge 42.4,53.2", tn = 16013, go = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge.", rw = { 22011 } },
            }},
            [2] = { name = "T0.5 · Belt & Gloves", lv = 58, zone = "Ironforge / Gadgetzan", rew = { 22010, 22015 }, note = "A long chain between Ironforge (Orgrimmar) and Gadgetzan. Collect 12 ectoplasm each in Silithus, Winterspring and the Eastern Plaguelands; keep the Extra-Dimensional Ghost Revealer you get, it is needed later.", flow = {
                { id = 8922, sl = 58, s = "A", q = "A Supernatural Device", f = "Deliana", fl = "Ironforge 42.4,53.2", fn = 16013, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris." },
                { id = 8921, sl = 58, s = "A", q = "The Ectoplasmic Distiller", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", rw = { 22320 } },
                { id = 8924, sl = 58, s = "A", q = "Hunting for Ectoplasm", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands.  Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan." },
                { id = 8925, sl = 58, s = "A", q = "A Portable Power Source", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan." },
                { id = 8928, sl = 58, s = "A", q = "A Shifty Merchant", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan." },
