            [1] = { name = "T0.5 · Bracers", lv = 58, zone = "Ironforge / Orgrimmar", rew = { 22011 }, note = "The first stage upgrades only the bracers. Find your faction's contact in your capital and hand in the materials and your old bracers; this step also unlocks every later stage.", flow = {
