            }},
            [2] = { name = "T0.5 · Belt & Gloves", lv = 58, zone = "Ironforge / Gadgetzan", rew = { 22010, 22015 }, note = "A long chain between Ironforge (Orgrimmar) and Gadgetzan. Collect 12 ectoplasm each in Silithus, Winterspring and the Eastern Plaguelands; keep the Extra-Dimensional Ghost Revealer you get, it is needed later.", flow = {
                { id = 8923, sl = 58, s = "H", q = "A Supernatural Device", f = "Mokvar", fl = "Orgrimmar 38,37", fn = 16012, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Take the Sealed Venom Container to Mux Manascrambler in Gadgetzan." },
                { id = 8921, sl = 58, s = "H", q = "The Ectoplasmic Distiller", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", rw = { 22320 } },
