                { id = 8925, sl = 58, s = "H", q = "A Portable Power Source", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan." },
                { id = 8928, sl = 58, s = "H", q = "A Shifty Merchant", f = "Mux Manascrambler", fl = "Tanaris 52.4,27.2", fn = 16014, t = "Mux Manascrambler", tl = "Tanaris 52.4,27.2", tn = 16014, go = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan." },
